                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 sm:h-5 sm:w-5 text-white/60" />
                </div>
                <input
                  type="text"
                  placeholder="Rechercher un stagiaire..."
                  className="block w-full pl-10 pr-3 py-1.5 sm:py-2 bg-white/10 border border-white/20 rounded-md text-white placeholder-white/60 focus:outline-none focus:ring-2 focus:ring-white/50 focus:border-transparent text-xs sm:text-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              {isConfirmed && (
                <button
                  onClick={handleUnconfirm}
                  className="px-3 py-1.5 sm:px-4 sm:py-2 bg-red-600 hover:bg-red-700 text-white rounded-md text-xs sm:text-sm font-medium flex items-center gap-2 transition-colors"
                >
                  <XCircle className="h-4 w-4 sm:h-5 sm:w-5" />
                  <span className="hidden sm:inline">Déconfirmer</span>
                </button>
              )}
            </div>
          </div>
          <div className="mt-3 grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 sm:gap-4">
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-3 sm:p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-2 sm:p-3 mr-3">
                <Users className="h-4 w-4 sm:h-6 sm:w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-xs sm:text-sm">Stagiaires</p>
                <p className="text-xl sm:text-2xl font-bold">{totalInterns}</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-3 sm:p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-2 sm:p-3 mr-3">
                <Coffee className="h-4 w-4 sm:h-6 sm:w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-xs sm:text-sm">Petit-déjeuner</p>
                <p className="text-xl sm:text-2xl font-bold">{breakfastCount}</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-3 sm:p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-2 sm:p-3 mr-3">
                <Utensils className="h-4 w-4 sm:h-6 sm:w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-xs sm:text-sm">Déjeuner</p>
                <p className="text-xl sm:text-2xl font-bold">{lunchCount}</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-3 sm:p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-2 sm:p-3 mr-3">
                <Utensils className="h-4 w-4 sm:h-6 sm:w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-xs sm:text-sm">Dîner</p>
                <p className="text-xl sm:text-2xl font-bold">{dinnerCount}</p>
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur-sm rounded-lg p-3 sm:p-4 flex items-center">
              <div className="bg-white/20 rounded-full p-2 sm:p-3 mr-3">
                <UtensilsCrossed className="h-4 w-4 sm:h-6 sm:w-6 text-white" />
              </div>
              <div>
                <p className="text-white/70 text-xs sm:text-sm">Absents</p>
                <p className="text-xl sm:text-2xl font-bold">{absentInterns}</p>
              </div>
            </div>
          </div>
        </div>

        {error && (
          <div className="p-3 sm:p-4 mb-4 sm:mb-6 rounded-r-md bg-red-50 border-l-4 border-red-500 flex items-center gap-3">
            <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-red-500 flex-shrink-0" />
            <p className="text-xs sm:text-sm text-red-700">{error}</p>
          </div>
        )}

        {isLoading ? (
          <div className="flex justify-center items-center h-48 sm:h-64">
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="h-8 w-8 sm:h-10 sm:w-10 text-[#00717F] animate-spin" />
