            <div className="lg:col-span-3">
              <div className="bg-white rounded-xl shadow-md overflow-hidden border border-[#C8A45D/30]/50">
                <div className="bg-[#F5F6FA] p-4 sm:p-6 border-b border-[#C8A45D/30]/30">
