                    <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                      {filteredInterns.length === 0 ? (
                        <tr>
                          <td colSpan={4} className="py-4 px-4 text-center text-gray-500 text-xs sm:text-sm">
                            Aucun stagiaire trouvé
                          </td>
                        </tr>
                      ) : (
                        filteredInterns.map((intern) => {
                          const optOutForTomorrow = intern.mealOptOuts?.find((opt) => {
                            const optDate = new Date(opt.date)
                            return optDate.toDateString() === tomorrow.toDateString()
                          })
                          const optedOutMeals = optOutForTomorrow ? optOutForTomorrow.mealTypes : []
                          const preferredMeals = meals
                            ?.filter((meal) => !optedOutMeals.includes(meal.type))
                            .map((meal) =>
                              meal.type === "Breakfast"
                                ? "Petit-déjeuner"
                                : meal.type === "Lunch"
                                  ? "Déjeuner"
                                  : "Dîner",
                            )

                          return (
                            <tr key={intern._id} className="hover:bg-[#F5F6FA]/50 transition-colors duration-150">
                              <td className="py-3 px-4 text-xs sm:text-sm font-medium text-gray-900">{`${intern.First_Name} ${intern.Last_Name}`}</td>
                              <td className="py-3 px-4 text-xs sm:text-sm text-gray-700">
                                {intern.Gender === "Male" ? "Garçon" : "Fille"}
                              </td>
                              <td className="py-3 px-4 text-xs sm:text-sm text-gray-700">{intern.emplacement}</td>
                              <td className="py-3 px-4 text-xs sm:text-sm text-gray-700">
                                {preferredMeals?.length > 0 ? preferredMeals.join(", ") : "Aucun"}
                              </td>
                            </tr>
                          )
                        })
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>

            <div className="space-y-4 sm:space-y-6">
              <div className="bg-white rounded-xl shadow-md p-4 sm:p-6 border border-[#C8A45D/30]/50">
                <div className="mb-3 sm:mb-4">
                  <h2 className="text-base sm:text-lg font-bold text-[#00717F]">Distribution des Repas</h2>
                  <p className="text-gray-500 mt-1 text-xs sm:text-sm">Répartition par type de repas</p>
                </div>
                <MealDistributionChart
                  breakfastCount={breakfastCount}
                  lunchCount={lunchCount}
                  dinnerCount={dinnerCount}
                  totalInterns={totalInterns}
                />
              </div>

              <div className="bg-white rounded-xl shadow-md p-4 sm:p-6 border border-[#C8A45D/30]/50">
                <div className="mb-3 sm:mb-4">
                  <h2 className="text-base sm:text-lg font-bold text-[#00717F]">Diversité de Genre</h2>
                  <p className="text-gray-500 mt-1 text-xs sm:text-sm">Répartition des stagiaires par genre</p>
                </div>
                <GenderDistributionChart femaleCount={femaleCount} maleCount={maleCount} />
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  )
}

function MealDistributionChart({ breakfastCount, lunchCount, dinnerCount, totalInterns }) {
  const [progress, setProgress] = useState({
    breakfast: 0,
    lunch: 0,
    dinner: 0,
  })

  useEffect(() => {
    const timer = setTimeout(() => {
      setProgress({
        breakfast: breakfastCount,
        lunch: lunchCount,
        dinner: dinnerCount,
      })
    }, 300)

    return () => clearTimeout(timer)
  }, [breakfastCount, lunchCount, dinnerCount])

  const radius = 40
  const circumference = 2 * Math.PI * radius

  // Check if all meal counts are equal
  const areMealsEqual = breakfastCount === lunchCount && lunchCount === dinnerCount && breakfastCount > 0

  // Calculate total meals for proportional distribution if meals are different
  const totalMeals = breakfastCount + lunchCount + dinnerCount

  // Calculate percentages for each meal if they are different
  const breakfastPercentage = totalMeals > 0 ? (breakfastCount / totalMeals) * 100 : 0
  const lunchPercentage = totalMeals > 0 ? (lunchCount / totalMeals) * 100 : 0
  const dinnerPercentage = totalMeals > 0 ? (dinnerCount / totalMeals) * 100 : 0

  // Calculate dash arrays for each segment
  const breakfastDasharray = areMealsEqual ? `${circumference} ${circumference}` : `${(breakfastPercentage * circumference) / 100} ${circumference}`
  const lunchDasharray = areMealsEqual ? "0 0" : `${(lunchPercentage * circumference) / 100} ${circumference}`
  const dinnerDasharray = areMealsEqual ? "0 0" : `${(dinnerPercentage * circumference) / 100} ${circumference}`

  // Define colors: Green if equal, otherwise use existing colors
  const breakfastColor = areMealsEqual ? "#4CAF50" : "#00717F" // Green for equal, otherwise teal
  const lunchColor = areMealsEqual ? "#4CAF50" : "#C8A45D" // Green for equal, otherwise gold
  const dinnerColor = areMealsEqual ? "#4CAF50" : "#00717F80" // Green for equal, otherwise semi-transparent teal

  return (
    <div>
      <div className="flex justify-center mb-4 sm:mb-6 relative">
        <svg width="140" height="140" viewBox="0 0 100 100" className="transform -rotate-90">
          <circle cx="50" cy="50" r={radius} fill="transparent" stroke="#e5e7eb" strokeWidth="10" />
          <circle
            cx="50"
            cy="50"
            r={radius}
            fill="transparent"
            stroke={breakfastColor}
            strokeWidth="10"
            strokeDasharray={breakfastDasharray}
            strokeDashoffset={0}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-out"
          />
          <circle
            cx="50"
            cy="50"
            r={radius}
            fill="transparent"
            stroke={lunchColor}
            strokeWidth="10"
            strokeDasharray={lunchDasharray}
            strokeDashoffset={areMealsEqual ? 0 : -(breakfastPercentage * circumference) / 100}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-out"
          />
          <circle
            cx="50"
            cy="50"
            r={radius}
            fill="transparent"
            stroke={dinnerColor}
            strokeWidth="10"
            strokeDasharray={dinnerDasharray}
            strokeDashoffset={areMealsEqual ? 0 : -((breakfastPercentage + lunchPercentage) * circumference) / 100}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-out"
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-xs text-gray-500">Total</span>
          <span className="text-xl sm:text-2xl font-bold text-[#00717F]">{totalInterns}</span>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-2">
        <div className="flex flex-col items-center">
          <div className="flex items-center mb-1">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: breakfastColor }}></div>
            <span className="text-xs sm:text-sm font-medium">{breakfastCount}</span>
          </div>
          <span className="text-xs text-gray-500">Petit-déj.</span>
        </div>
        <div className="flex flex-col items-center">
          <div className="flex items-center mb-1">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: lunchColor }}></div>
            <span className="text-xs sm:text-sm font-medium">{lunchCount}</span>
          </div>
          <span className="text-xs text-gray-500">Déjeuner</span>
        </div>
        <div className="flex flex-col items-center">
          <div className="flex items-center mb-1">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: dinnerColor }}></div>
            <span className="text-xs sm:text-sm font-medium">{dinnerCount}</span>
          </div>
          <span className="text-xs text-gray-500">Dîner</span>
        </div>
      </div>
    </div>
  )
}

function GenderDistributionChart({ femaleCount, maleCount }) {
  const [femaleWidth, setFemaleWidth] = useState(0)
  const [maleWidth, setMaleWidth] = useState(0)

  const maxValue = Math.max(femaleCount, maleCount, 10)
  const femalePercentage = (femaleCount / maxValue) * 100
  const malePercentage = (maleCount / maxValue) * 100

  useEffect(() => {
    const timer = setTimeout(() => {
      setFemaleWidth(femalePercentage)
      setMaleWidth(malePercentage)
    }, 300)

    return () => clearTimeout(timer)
  }, [femalePercentage, malePercentage])

  return (
    <div className="space-y-3 sm:space-y-4">
      <div className="space-y-1">
        <div className="flex justify-between">
          <div className="text-xs sm:text-sm text-gray-700">Filles</div>
          <div className="text-xs sm:text-sm font-medium text-[#C8A45D]">{femaleCount}</div>
        </div>
        <div className="h-5 sm:h-6 bg-[#F5F6FA] rounded-sm relative">
          <div
            className="h-full bg-[#C8A45D] rounded-sm transition-all duration-1000 ease-out"
            style={{ width: `${femaleWidth}%` }}
          ></div>
        </div>
      </div>

      <div className="space-y-1">
        <div className="flex justify-between">
          <div className="text-xs sm:text-sm text-gray-700">Garçons</div>
          <div className="text-xs sm:text-sm font-medium text-[#00717F]">{maleCount}</div>
        </div>
        <div className="h-5 sm:h-6 bg-[#F5F6FA] rounded-sm relative">
          <div
            className="h-full bg-[#00717F] rounded-sm transition-all duration-1000 ease-out"
            style={{ width: `${maleWidth}%` }}
          ></div>
        </div>
      </div>

      <div className="flex justify-between pt-2 text-xs text-gray-500">
        <span>0</span>
        <span>{Math.round(maxValue * 0.25)}</span>
        <span>{Math.round(maxValue * 0.5)}</span>
        <span>{Math.round(maxValue * 0.75)}</span>
        <span>{maxValue}</span>
      </div>
    </div>
  )
}
